// Build the ranked Tier 1 digest (HTML + plain text).
const rows = $input.all().map((i) => i.json).filter((r) => r && r.id);
const date = new Date().toISOString().slice(0, 10);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const verticalLabel = {
  personal_injury_law: 'Personal injury law',
  medical_practice: 'Medical practice',
  home_services: 'Home services',
};

const tr = rows
  .map((r, i) => {
    const sig = r.signals || {};
    const notes = [];
    if (sig.email_pending) notes.push('email pending');
    if (sig.active_job_postings) notes.push(sig.active_job_postings + ' open roles');
    return (
      '<tr>' +
      '<td style="padding:6px 10px;">' + (i + 1) + '</td>' +
      '<td style="padding:6px 10px;"><strong>' + esc(r.company_name) + '</strong><br><a href="https://' + esc(r.domain) + '">' + esc(r.domain) + '</a></td>' +
      '<td style="padding:6px 10px;">' + esc(verticalLabel[r.vertical] || r.vertical) + '</td>' +
      '<td style="padding:6px 10px;">' + esc(r.city || '') + '</td>' +
      '<td style="padding:6px 10px;">' + esc(r.contact_name || '-') + '<br><small>' + esc(r.contact_title || '') + '</small></td>' +
      '<td style="padding:6px 10px;">' + esc(r.contact_email || '(pending)') + '<br>' + esc(r.contact_phone || '') + '</td>' +
      '<td style="padding:6px 10px;text-align:center;"><strong>' + r.intent_score + '</strong></td>' +
      '<td style="padding:6px 10px;">' + esc(r.outreach_status) + (notes.length ? '<br><small>' + esc(notes.join(', ')) + '</small>' : '') + '</td>' +
      '</tr>'
    );
  })
  .join('');

const html =
  '<h2>Tier 1 AI-automation prospects - ' + date + '</h2>' +
  '<p>' + rows.length + ' businesses with <strong>no AI tooling detected</strong>, ranked by intent score (highest first).</p>' +
  '<table border="1" cellspacing="0" style="border-collapse:collapse;border-color:#ddd;font-family:sans-serif;font-size:14px;">' +
  '<tr style="background:#f5f5f5;"><th style="padding:6px 10px;">#</th><th style="padding:6px 10px;">Company</th><th style="padding:6px 10px;">Vertical</th><th style="padding:6px 10px;">City</th><th style="padding:6px 10px;">Contact</th><th style="padding:6px 10px;">Email / Phone</th><th style="padding:6px 10px;">Intent</th><th style="padding:6px 10px;">Status</th></tr>' +
  tr +
  '</table>' +
  '<p><strong>To queue a prospect for a Vapi call</strong>, set its status to approved in Supabase:<br>' +
  '<code>update prospects set outreach_status = \'approved\' where domain = \'&lt;domain&gt;\';</code></p>' +
  '<p style="color:#888;font-size:12px;">Opt-outs: add the domain/email/phone to the <code>suppression_list</code> table and the prospect is excluded from all future digests, enrichment, and calls. See docs/compliance.md.</p>';

const text = rows
  .map((r, i) => (i + 1) + '. ' + r.company_name + ' (' + r.domain + ') - ' + (verticalLabel[r.vertical] || r.vertical) + ', intent ' + r.intent_score + ', ' + (r.contact_email || 'email pending') + ' ' + (r.contact_phone || ''))
  .join('\n');

return [{ json: { subject: 'Tier 1 AI-Automation Prospects - ' + date + ' (' + rows.length + ')', html, text } }];
